+#!/usr/bin/env node
+/** CLI for task planner: plan command. */
+import * as fs from "node:fs";
+import * as path from "node:path";
+import { parseTasks } from "./tasks.ts";
+import { planOrder } from "./planner.ts";
+import { TaskPlanError } from "./errors.ts";
+
+const USAGE = "Usage: node src/cli.ts plan <file> [--json]";
+
+function printUsage(): string {
+  return USAGE + "\n";
+}
+
+function exitWithUsage(code: number, extraLine?: string): never {
+  if (extraLine !== undefined) {
+    process.stderr.write(extraLine + "\n" + printUsage());
+  } else {
+    process.stderr.write(printUsage());
+  }
+  process.exit(code);
+}
+
+function main(): void {
+  const rawArgs = process.argv.slice(2);
+
+  if (rawArgs.length === 0) {
+    exitWithUsage(2);
+  }
+
+  const command = rawArgs[0];
+  if (command !== "plan") {
+    exitWithUsage(2);
+  }
+
+  // Parse args after "plan"
+  let filePath: string | undefined = undefined;
+  let format: string | undefined = undefined; // "text" | "json" | "dot"
+  let jsonCount = 0;
+
+  let i = 1;
+  while (i < rawArgs.length) {
+    const arg = rawArgs[i]!;
+    if (arg === "--json") {
+      jsonCount++;
+      if (jsonCount > 1) {
+        exitWithUsage(2);
+      }
+      if (format === undefined) {
+        format = "json";
+      } else if (format !== "json") {
+        // conflicting format specifications
+        exitWithUsage(2);
+      }
+      i++;
+    } else if (arg === "--format") {
+      const val = rawArgs[i + 1];
+      if (val === undefined) {
+        exitWithUsage(2);
+      }
+      if (val !== "json" && val !== "text" && val !== "dot") {
+        exitWithUsage(2);
+      }
+      if (format !== undefined) {
+        exitWithUsage(2);
+      }
+      format = val;
+      i += 2;
+    } else if (arg.startsWith("--format=")) {
+      const val = arg.slice("--format=".length);
+      if (val !== "json" && val !== "text" && val !== "dot") {
+        exitWithUsage(2);
+      }
+      if (format !== undefined) {
+        exitWithUsage(2);
+      }
+      format = val;
+      i++;
+    } else if (arg.startsWith("--")) {
+      // unknown option
+      exitWithUsage(2);
+    } else {
+      // positional argument (file)
+      if (filePath !== undefined) {
+        // extra argument
+        exitWithUsage(2);
+      }
+      filePath = arg;
+      i++;
+    }
+  }
+
+  if (filePath === undefined) {
+    exitWithUsage(2);
+  }
+
+  if (format === undefined) {
+    format = "text";
+  }
+
+  // Resolve relative file path against cwd
+  const resolved = path.resolve(process.cwd(), filePath);
+
+  let content: string;
+  try {
+    content = fs.readFileSync(resolved, "utf8");
+  } catch (e) {
+    const msg = e instanceof Error ? e.message : String(e);
+    // Spec: one line `error: <reason>`, then a usage message, exit 2
+    process.stderr.write(`error: ${msg}\n` + printUsage());
+    process.exit(2);
+  }
+
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(content);
+  } catch (e) {
+    const msg = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error INVALID_JSON: ${msg}\n`);
+    process.exit(1);
+  }
+
+  let tasks;
+  let result;
+  try {
+    tasks = parseTasks(parsed);
+    result = planOrder(tasks);
+  } catch (e) {
+    if (e instanceof TaskPlanError) {
+      const code = (e as TaskPlanError).code;
+      const msg = e instanceof Error ? e.message : String(e);
+      process.stderr.write(`error ${code}: ${msg}\n`);
+      process.exit(1);
+    } else {
+      // rethrow unexpected
+      throw e;
+    }
+  }
+
+  // Success output
+  if (format === "json") {
+    process.stdout.write(JSON.stringify({ order: result.order, stages: result.stages }) + "\n");
+  } else if (format === "dot") {
+    // DOT format: digraph with nodes and dependency edges
+    let out = "digraph {\n";
+    for (const id of result.order) {
+      out += `  "${id}";\n`;
+    }
+    // edges from dependency -> task
+    // Need task map for dependsOn
+    const idToDeps = new Map<string, string[]>();
+    for (const t of tasks!) {
+      idToDeps.set(t.id, t.dependsOn);
+    }
+    for (const id of result.order) {
+      const deps = idToDeps.get(id) ?? [];
+      for (const dep of deps) {
+        out += `  "${dep}" -> "${id}";\n`;
+      }
+    }
+    out += "}\n";
+    process.stdout.write(out);
+  } else {
+    // text (default)
+    if (result.order.length === 0 && result.stages.length === 0) {
+      process.stdout.write("Order:\n");
+    } else {
+      let out = "";
+      for (let k = 0; k < result.stages.length; k++) {
+        const stage = result.stages[k]!;
+        out += `Stage ${k + 1}: ${stage.join(", ")}\n`;
+      }
+      out += `Order: ${result.order.join(", ")}\n`;
+      process.stdout.write(out);
+    }
+  }
+  process.exit(0);
+}
+
+main();
