+/** Planning utilities for ordering tasks by dependencies and priority. */
+import { TaskPlanError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of {@link planOrder}: execution order and parallel stages. */
+export interface PlanResult {
+  /** Every task id, in execution order. */
+  order: string[];
+  /** tasks that can run at the earliest in round k */
+  stages: string[][];
+}
+
+/** Duplicate task ids found in the input. */
+export class DuplicateTaskError extends TaskPlanError {
+  /** Every id that occurs more than once, each once, ordered by first position. */
+  readonly taskIds: string[];
+  /**
+   * @param taskIds ids that appear more than once
+   */
+  constructor(taskIds: string[]) {
+    super("DUPLICATE_ID", `duplicate task ids: ${taskIds.join(", ")}`);
+    this.taskIds = taskIds;
+  }
+}
+
+/** A task depends on an id that does not exist. */
+export class UnknownDependencyError extends TaskPlanError {
+  /** The task that has the missing dependency. */
+  readonly taskId: string;
+  /** The missing dependency id. */
+  readonly dependency: string;
+  /**
+   * @param taskId task that declares the dependency
+   * @param dependency missing id
+   */
+  constructor(taskId: string, dependency: string) {
+    super("UNKNOWN_DEPENDENCY", `unknown dependency ${dependency} for task ${taskId}`);
+    this.taskId = taskId;
+    this.dependency = dependency;
+  }
+}
+
+/** A dependency cycle was found. */
+export class CycleError extends TaskPlanError {
+  /** Closed path: first and last ids equal, each id depends on the id after it. */
+  readonly cycle: string[];
+  /**
+   * @param cycle closed simple cycle path
+   */
+  constructor(cycle: string[]) {
+    super("CYCLE", `cycle detected: ${cycle.join(" -> ")}`);
+    this.cycle = cycle;
+  }
+}
+
+/**
+ * Determine a deterministic execution order and stages for the given tasks.
+ *
+ * R1: topological order, at each step pick ready task with highest priority
+ * (tie: input order). R2: stages by longest dependency chain.
+ *
+ * @param tasks tasks in the shape `parseTasks` returns
+ * @returns plan with `order` and `stages`
+ * @throws {DuplicateTaskError} if any id occurs more than once
+ * @throws {UnknownDependencyError} if a dependency id does not exist
+ * @throws {CycleError} if dependencies contain a cycle
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  // R3 step 1: duplicate ids
+  const counts = new Map<string, number>();
+  const firstPos = new Map<string, number>();
+  for (let i = 0; i < tasks.length; i++) {
+    const id = tasks[i]!.id;
+    if (!counts.has(id)) {
+      counts.set(id, 1);
+      firstPos.set(id, i);
+    } else {
+      counts.set(id, (counts.get(id) ?? 0) + 1);
+    }
+  }
+  const dups: string[] = [];
+  for (const [id, c] of counts) {
+    if (c > 1) dups.push(id);
+  }
+  if (dups.length > 0) {
+    dups.sort((a, b) => (firstPos.get(a) ?? 0) - (firstPos.get(b) ?? 0));
+    throw new DuplicateTaskError(dups);
+  }
+
+  if (tasks.length === 0) {
+    return { order: [], stages: [] };
+  }
+
+  const idSet = new Set<string>();
+  const idToIndex = new Map<string, number>();
+  const idToTask = new Map<string, TaskSpec>();
+  for (let i = 0; i < tasks.length; i++) {
+    const t = tasks[i]!;
+    idSet.add(t.id);
+    idToIndex.set(t.id, i);
+    idToTask.set(t.id, t);
+  }
+
+  // R3 step 2: unknown dependency - earliest task, earliest entry
+  for (let i = 0; i < tasks.length; i++) {
+    const t = tasks[i]!;
+    for (let j = 0; j < t.dependsOn.length; j++) {
+      const dep = t.dependsOn[j]!;
+      if (!idSet.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  // Build deduped dependencies adjacency
+  const depsMap = new Map<string, string[]>(); // id -> unique deps (preserving first occurrence order)
+  const dependentsMap = new Map<string, string[]>(); // id -> list of tasks that depend on it
+  const indegree = new Map<string, number>();
+  for (const t of tasks) {
+    const seen = new Set<string>();
+    const uniq: string[] = [];
+    for (const d of t.dependsOn) {
+      if (!seen.has(d)) {
+        seen.add(d);
+        uniq.push(d);
+      }
+    }
+    depsMap.set(t.id, uniq);
+    indegree.set(t.id, uniq.length);
+    for (const d of uniq) {
+      let arr = dependentsMap.get(d);
+      if (!arr) {
+        arr = [];
+        dependentsMap.set(d, arr);
+      }
+      arr.push(t.id);
+    }
+  }
+
+  // R3 step 3: cycle detection - iterative DFS to avoid stack overflow
+  {
+    const state = new Map<string, number>(); // 0 unvisited, 1 visiting, 2 done
+    for (const t of tasks) state.set(t.id, 0);
+    const idStack: string[] = [];
+    const posInStack = new Map<string, number>();
+    // frame stack
+    type Frame = { id: string; deps: string[]; idx: number };
+    const frameStack: Frame[] = [];
+
+    for (const start of tasks) {
+      if ((state.get(start.id) ?? 0) !== 0) continue;
+      // push start
+      state.set(start.id, 1);
+      posInStack.set(start.id, idStack.length);
+      idStack.push(start.id);
+      frameStack.push({ id: start.id, deps: depsMap.get(start.id) ?? [], idx: 0 });
+
+      while (frameStack.length > 0) {
+        const frame = frameStack[frameStack.length - 1]!;
+        if (frame.idx < frame.deps.length) {
+          const dep = frame.deps[frame.idx++]!;
+          const col = state.get(dep) ?? 0;
+          if (col === 0) {
+            state.set(dep, 1);
+            posInStack.set(dep, idStack.length);
+            idStack.push(dep);
+            frameStack.push({ id: dep, deps: depsMap.get(dep) ?? [], idx: 0 });
+          } else if (col === 1) {
+            const startIdx = posInStack.get(dep) ?? 0;
+            const cycle = idStack.slice(startIdx);
+            cycle.push(dep);
+            throw new CycleError(cycle);
+          } else {
+            // done, continue
+          }
+        } else {
+          state.set(frame.id, 2);
+          posInStack.delete(frame.id);
+          idStack.pop();
+          frameStack.pop();
+        }
+      }
+    }
+  }
+
+  // Build order via Kahn with priority queue
+  const round = new Map<string, number>();
+
+  // heap
+  const heap: string[] = [];
+  function compare(a: string, b: string): number {
+    const ta = idToTask.get(a)!;
+    const tb = idToTask.get(b)!;
+    if (ta.priority !== tb.priority) return ta.priority - tb.priority; // higher priority larger
+    // tie: earlier input first => smaller index is higher
+    const ia = idToIndex.get(a) ?? 0;
+    const ib = idToIndex.get(b) ?? 0;
+    return ib - ia;
+  }
+  function heapPush(id: string): void {
+    heap.push(id);
+    let i = heap.length - 1;
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      if (compare(heap[i]!, heap[p]!) <= 0) break;
+      const tmp = heap[i]!;
+      heap[i] = heap[p]!;
+      heap[p] = tmp;
+      i = p;
+    }
+  }
+  function heapPop(): string | undefined {
+    if (heap.length === 0) return undefined;
+    const top = heap[0]!;
+    const last = heap.pop()!;
+    if (heap.length > 0) {
+      heap[0] = last;
+      let i = 0;
+      while (true) {
+        const l = i * 2 + 1;
+        const r = l + 1;
+        let best = i;
+        if (l < heap.length && compare(heap[l]!, heap[best]!) > 0) best = l;
+        if (r < heap.length && compare(heap[r]!, heap[best]!) > 0) best = r;
+        if (best === i) break;
+        const tmp = heap[i]!;
+        heap[i] = heap[best]!;
+        heap[best] = tmp;
+        i = best;
+      }
+    }
+    return top;
+  }
+
+  for (const t of tasks) {
+    if ((indegree.get(t.id) ?? 0) === 0) {
+      heapPush(t.id);
+    }
+  }
+
+  const order: string[] = [];
+  while (heap.length > 0) {
+    const cur = heapPop()!;
+    order.push(cur);
+    // compute round for cur
+    const deps = depsMap.get(cur) ?? [];
+    if (deps.length === 0) {
+      round.set(cur, 0);
+    } else {
+      let maxR = -1;
+      for (const d of deps) {
+        const r = round.get(d) ?? 0;
+        if (r > maxR) maxR = r;
+      }
+      round.set(cur, maxR + 1);
+    }
+    const dependents = dependentsMap.get(cur) ?? [];
+    for (const depId of dependents) {
+      const nd = (indegree.get(depId) ?? 0) - 1;
+      indegree.set(depId, nd);
+      if (nd === 0) heapPush(depId);
+    }
+  }
+
+  // Build stages grouped by round
+  let maxRound = -1;
+  for (const v of round.values()) if (v > maxRound) maxRound = v;
+  const stages: string[][] = maxRound >= 0 ? Array.from({ length: maxRound + 1 }, () => []) : [];
+  for (const id of order) {
+    const r = round.get(id) ?? 0;
+    stages[r]!.push(id);
+  }
+  // Within each stage, order by priority desc then input position
+  for (let k = 0; k < stages.length; k++) {
+    const arr = stages[k]!;
+    arr.sort((a, b) => {
+      const ta = idToTask.get(a)!;
+      const tb = idToTask.get(b)!;
+      if (ta.priority !== tb.priority) return tb.priority - ta.priority;
+      return (idToIndex.get(a) ?? 0) - (idToIndex.get(b) ?? 0);
+    });
+  }
+
+  return { order, stages };
+}
